using System;using System.Collections.Generic;using UnityEngine;using LestingCraft.Gameplay;using LestingCraft.World;
class CheckLivingCore
{
 static int checks;static void Check(bool b,string label){checks++;if(!b)throw new Exception(label);}
 static void Main()
 {
  var v=new SurvivalState{health=63};v.Normalize();Check(v.body.hp.Length==6&&v.body.hp[4]==63,"legacy six-zone migration");v.Respawn();v.DamagePart(50,GameMode.Survival,BodyPart.LeftLeg);Check(v.body.hp[4]<50&&v.body.hp[5]==100,"localized leg health");Check(v.body.Movement<1&&!v.body.CanSprint,"leg movement consequences");Check(v.body.Treat(),"injury treatment");Check(v.body.hp[4]>44,"treatment improves wound");v.Respawn();v.DamagePart(35,GameMode.Survival,BodyPart.RightArm);Check(v.body.Dexterity<1,"arm action slowdown");v.Respawn();v.DamagePart(60,GameMode.Survival,BodyPart.Head);Check(v.dead&&v.health==0,"vital injury kills");v.Respawn();Check(!v.dead&&v.body.hp[0]==100,"respawn resets wounds");v.DamagePart(1000,GameMode.Creative,BodyPart.Head);Check(!v.dead&&v.health==100,"creative injury immunity");
  var edits=new Dictionary<Vector3Int,ushort>();Func<int,int,int,ushort> get=(x,y,z)=>edits.TryGetValue(new Vector3Int(x,y,z),out var b)?b:(ushort)(y<50?1:0);Action<int,int,int,ushort> set=(x,y,z,b)=>edits[new Vector3Int(x,y,z)]=b;var sim=new LivingSimulation(2506,null,get,set);
  set(300,56,300,6);sim.Wake(new Vector3Int(300,56,300));for(int i=0;i<10;i++)sim.Step(.05f,600,270,51.6f,270,"local");Check(sim.Drops.Count==1&&sim.Drops[0].blockBody,"unsupported sand is physical entity");Check(sim.Drops[0].vy<0&&sim.Drops[0].y<56,"fall acceleration");for(int i=0;i<130;i++)sim.Step(.05f,600,270,51.6f,270,"local");Check(get(300,50,300)==6&&sim.Drops.Count==0,"falling sand settles without tunnelling");
  var d=sim.Drop(140,1,0,new Vector3(304.5f,70,304.5f),Vector3.down*24);for(int i=0;i<80;i++)sim.Step(.05f,600,270,51.6f,270,"local");Check(d.y>=50&&d.y<50.3,"item collision floor");Check(LivingSimulation.Floats(4)&&!LivingSimulation.Floats(140),"wood floats / metal sinks");
  set(310,50,310,7);sim.Edited(new Vector3Int(310,50,310));for(int i=0;i<40;i++)sim.Step(.05f,600,270,51.6f,270,"local");Check(get(311,50,310)==7,"fluid lateral spread");Check(sim.Height(311,50,310)<1,"meshed fractional fluid height");
  var a=new LivingActor{id="cat",kind=1,owner="local",x=320.5f,y=50,z=320.5f,hx=320.5f,hy=50,hz=320.5f};sim.Actors.Add(a);for(int i=0;i<30;i++)sim.Step(.05f,600,325,51.6f,320.5f,"local");Check(a.x>320.5f,"tame cat follows");a.sitting=true;float before=a.x;for(int i=0;i<30;i++)sim.Step(.05f,600,325,51.6f,320.5f,"local");Check(a.x==before,"sitting cat stays");var saved=sim.Save();var restored=new LivingSimulation(2506,saved,get,set);Check(restored.Actors.Count==1&&restored.Actors[0].owner=="local"&&restored.Actors[0].sitting,"persistent cat ownership and sitting");
  var bag=new Inventory();bag.Add(153,1);bag.slots[0].durability=21;var item=bag.slots[0].Clone();bag.Remove(153,1);Check(bag.AddStack(item)&&bag.slots[0].durability==21,"pickup preserves worn durability");
  var chunk=new ChunkData();chunk.SetBlock(5,50,5,7);chunk.SetBlock(6,50,5,7);var mesh=ChunkMesher.Build(chunk,0,0,(x,y,z)=>(ushort)0,0,false,0,null,(x,y,z)=>x==5?.875f:.5f);bool fractional=false;foreach(var p in mesh.Vertices)if(Math.Abs(p.y-50.875f)<.001)fractional=true;Check(fractional&&mesh.WaterTriangles.Count>0,"actual fluid mesh has fractional level");
  uint random=6;for(int i=0;i<20000;i++){random=unchecked(random*1664525+1013904223);int x=(int)(random%2048)-1024;random=unchecked(random*1664525+1013904223);int z=(int)(random%2048)-1024,y=(int)(random%99)+1;Check(TerrainGenerator.SampleContent(x,y,z,2506,Dimension.Lestingia,5)==TerrainGenerator.SampleContent(x,y,z,2506,Dimension.Lestingia,6),"unchanged static landscapes");}
  Console.WriteLine("PASS "+checks+" managed checks: localized injuries, treatment, fall acceleration/collision, fluids/mesh, cat follow/sit/save, worn-item pickup and 20000 content5/content6 terrain probes. Actual Unity managed assemblies; no native engine or GPU.");
 }
}
